#!/usr/bin/env python3
"""Generate the Bengali campaign-pricing design audio with Edge TTS.

The script answers one question: how can a landing page sell an existing
product at a campaign price without changing the product details page price?
It covers the database fields, cart/order snapshot, inventory, variants,
coupons, expiry and the admin experience.

Usage:
    python3 tools/generate_landing_campaign_pricing_audio.py
    python3 tools/generate_landing_campaign_pricing_audio.py --out /tmp/pricing.mp3
"""

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from tts_utils import audio_seconds, synthesize

DEFAULT_VOICE = "bn-BD-PradeepNeural"
DEFAULT_OUT = Path("/home/sahon/Music/mp3/new evo/landing-campaign-pricing-bn.mp3")

SCRIPT = """
আসসালামু আলাইকুম। ভাইয়া, আজকের প্রশ্নটা খুব গুরুত্বপূর্ণ। ল্যান্ডিং পেজে আমরা প্রোডাক্টের সাধারণ দামের চেয়ে অনেক কম দামে বিক্রি করব। কিন্তু প্রোডাক্ট ডিটেইলস পেজে দামটা আগের মতোই থাকবে। তাহলে ওই ডিসকাউন্ট দামটা ডাটাবেজে কোথায় রাখব? আর যদি প্রোডাক্টের দামই না বদলাই, তাহলে ল্যান্ডিং পেজের আলাদা মূল্যটাই বা কী রইল? প্রথমে সংক্ষেপে উত্তর, তারপর ধাপে ধাপে।

সংক্ষেপে উত্তর হলো — প্রোডাক্টের new_price এক ইঞ্চিও বদলাব না। প্রোডাক্ট টেবিল হলো স্থায়ী ক্যাটালগ। ল্যান্ডিং পেজের দাম হবে একটা আলাদা ক্যাম্পেইন-নির্দিষ্ট দাম, যা ক্যাম্পেইন টেবিলে থাকবে। ক্যাম্পেইন পেজ ওই দাম দেখাবে, প্রোডাক্ট পেজ আগের দামই দেখাবে। কার্টে ক্যাম্পেইনের দাম বসবে, আর অর্ডার ডিটেইলসে ওই দাম স্ন্যাপশট হয়ে যাবে। ইনভেন্টরি একই প্রোডাক্টের স্টক থেকেই কমবে। কোনো ডুপ্লিকেট প্রোডাক্ট নেই, ডুপ্লিকেট এসকেইউ নেই, আলাদা অর্ডার সিস্টেমও নেই।

একটা সহজ উপমা দিই। আপনি নিজেই বলেছিলেন, এটা একজন নারীকে মেকআপ করানোর মতো। মানুষটা একই, শুধু উপস্থাপনাটা আলাদা। প্রোডাক্টও তাই। প্রোডাক্টের মূল পরিচয়, স্টক, দামের ভিত্তি একই থাকবে। ল্যান্ডিং পেজ হলো তার সিজনাল সাজ। শীতে খেজুর, বর্ষায় মধু, উৎসবে গার্মেন্টস — প্রোডাক্ট একই, ক্যাম্পেইন আলাদা। মেকআপ শেষ হলে মুখটা তো বদলে যায় না, শুধু সাজটা সরে যায়। ক্যাম্পেইন শেষ হলে ল্যান্ডিং পেজের অফার শেষ, প্রোডাক্ট পেজ আবার সাধারণ দামেই চলবে।

এখন বাস্তব কোড। আমাদের অর্ডার সেভ ফাংশন প্রোডাক্টের দাম নতুন করে হিসাব করে না। সে কার্টের লাইন থেকেই সাবটোটাল বানায়। `CustomerController@order_save`-এ কার্টের প্রতিটা লাইনের price আর qty গুণ করে সাবটোটাল করা হয়। তারপর `order_details`-এ sale_price হিসেবে কার্টের price-ই লেখা হয়, purchase_price হিসেবে কার্টের options থেকে আসা ক্রয়মূল্য লেখা হয়। মানে আমরা যদি কার্টে ক্যাম্পেইনের দাম বসাতে পারি, তাহলে অর্ডার নিজে থেকেই ওই দামে হবে। প্রোডাক্ট টেবিলে হাত দিতে হবে না। পেমেন্টও orders.amount থেকেই যায়, তাই বিকাশ, কার্ড বা ক্যাশ অন ডেলিভারি সবখানে ক্যাম্পেইনের দামই চার্জ হবে।

তাহলে ডাটাবেজে কী যোগ করব? প্রথমে campaigns টেবিলে পাঁচটা জিনিস। এক, product_id — কোন প্রোডাক্টের উপর ক্যাম্পেইন। দুই, campaign_price — ক্যাম্পেইনের বিক্রয়মূল্য। তিন, campaign_price_enabled — চালু বা বন্ধ করার সুইচ। চার, campaign_discount_percent — যেসব প্রোডাক্টে variant আছে, তাদের জন্য শতাংশ ছাড়। পাঁচ, allow_coupon — এই অফারে কুপন লাগবে কি না, ডিফল্টে বন্ধ। আর order_details টেবিলে দুইটা জিনিস। এক, campaign_id — কোন ক্যাম্পেইন থেকে অর্ডার এল। দুই, regular_price — ক্যাম্পেইনের আগে যে দাম ছিল, মানে প্রোডাক্টের নতুন দাম বা variant-এর কার্যকর দাম। sale_price আগের মতোই আসল চার্জ করা দাম থাকবে, purchase_price আগের মতোই ক্রয়মূল্য থাকবে।

কেন campaign_price প্রোডাক্টে নয়? কারণ প্রোডাক্টের দাম হলে সেটা সব জায়গায় লাগবে। প্রোডাক্ট ডিটেইলস, সার্চ, ক্যাটাগরি, অন্য ক্যাম্পেইন — সব জায়গায় নতুন দাম দেখাবে। পুরনো দাম হারিয়ে যাবে। আর ক্যাম্পেইনের শুরু-শেষের সীমা থাকবে না। campaign_price আলাদা থাকলে একই প্রোডাক্ট এক ক্যাম্পেইনে ৮৯৯ টাকা, আরেক ক্যাম্পেইনে ৯৯৯ টাকা, আবার প্রোডাক্ট পেজে ১২০০ টাকা — সবই সম্ভব, আর প্রতিটার হিসাব আলাদা থাকে।

এখন দামটা কার্টে কীভাবে যাবে? ল্যান্ডিং পেজের অর্ডার ফর্মে product_id আর quantity-এর সাথে hidden campaign_id যাবে। কখনো দাম পোস্ট করব না। `landingOrder` সার্ভারে ক্যাম্পেইন লোড করবে, দেখবে ক্যাম্পেইন সক্রিয় কি না, শুরু আর শেষ তারিখের ভিতরে আছে কি না, পোস্ট করা প্রোডাক্টের সাথে ক্যাম্পেইনের প্রোডাক্ট মিলছে কি না। তারপর একটা জায়গায় দাম হিসাব করবে। এই একটাই হিসাব — Blade-এ আলাদা, জাভাস্ক্রিপ্টে আলাদা, কার্টে আলাদা — এমন হবে না। একটাই সার্ভিস, নাম দিলাম CampaignPricing। সে প্রোডাক্ট আর variant দেখে কার্যকর দাম বের করবে, তারপর ক্যাম্পেইনের নিয়ম লাগাবে।

নিয়মটা সহজ। আগে variant-এর কার্যকর দাম বের করব — variant-এ price_override থাকলে সেটা, নাহলে প্রোডাক্টের new_price। এরপর variant-এ discount_price থাকলে এবং সেটা কম হলে, সেটাই আসল বিক্রয়মূল্য। এইটা প্রোডাক্ট ডিটেইলস পেজ আগেই করে। কিন্তু আমাদের `landingOrder` এখন variant-এর discount_price দেখে না — এটা একটা বাগ। ক্যাম্পেইন প্রাইস যোগ করার আগে এই বাগটা ঠিক করতে হবে, নাহলে প্রোডাক্ট পেজে একটা দাম দেখাবে আর ল্যান্ডিং অর্ডারে আরেকটা দাম চার্জ হবে। এরপর যদি ক্যাম্পেইন চালু থাকে এবং campaign_discount_percent দেওয়া থাকে, তাহলে কার্যকর দামের উপর ওই শতাংশ ছাড়। আর যদি সাধারণ প্রোডাক্ট হয় এবং fixed campaign_price দেওয়া থাকে, তাহলে সরাসরি ওই দাম। যদি ক্যাম্পেইনের দাম কার্যকর দামের চেয়ে কম না হয়, বা শূন্য হয়, তাহলে ক্যাম্পেইনের দাম ব্যবহার করব না — প্রোডাক্টের দামেই বিক্রি হবে, আর অ্যাডমিন একটা সতর্কবার্তা দেখবে। নকল ডিসকাউন্ট দেখানো যাবে না।

কার্ট লাইনে শুধু দাম বসালেই হবে না। options-এ campaign_id, regular_price, campaign_price, price_source আর campaign_slug রাখতে হবে। আর একটা গুরুত্বপূর্ণ কথা — বর্তমানে `landingOrder` কার্টে আগের আইটেম খোঁজে শুধু product_id আর variant_id দিয়ে। ধরুন একজন আগে প্রোডাক্ট পেজ থেকে ১২০০ টাকায় প্রোডাক্টটা কার্টে যোগ করেছে, পরে ল্যান্ডিং পেজ থেকে ৮৯৯ টাকায় যোগ করল। যদি ম্যাচে campaign_id না থাকে, তাহলে سیستم পুরনো লাইনটাই আপডেট করে দিতে পারে, আর দাম ১২০০-ই থেকে যাবে। তাই ম্যাচে product, variant আর campaign_id — তিনটাই থাকতে হবে। ক্যাম্পেইনের লাইন আর সাধারণ লাইন আলাদা থাকবে। আর অ্যাড টু কার্ট ট্র্যাকিংয়ে এখন প্রোডাক্টের new_price পাঠানো হয়; সেখানে কার্টে যে দামটাจริงে বসেছে, সেটাই পাঠাতে হবে, সাথে campaign_id।

অর্ডার সেভে বড় পরিবর্তন লাগবে না। `order_save` আগেই কার্টের price থেকে sale_price লিখছে। শুধু দুটো লাইন যোগ করব — order_details.campaign_id আর order_details.regular_price। purchase_price আগের মতোই থাকবে। orders.discount কিন্তু কুপনের জন্য, ক্যাম্পেইনের জন্য নয়। ক্যাম্পেইনের ছাড় আমরা orders.discount-এ ঢুকব না; নাহলে কুপন রিপোর্ট আর ক্যাম্পেইন রিপোর্ট মিশে যাবে। ক্যাম্পেইনের ছাড় বোঝা যাবে regular_price মাইনাস sale_price থেকে, প্রতি লাইনে। ইনভেন্টরি? স্টক চেক আর ডিক্রিমেন্ট আগের মতোই প্রোডাক্ট বা variant-এর qty দিয়ে হবে। দাম কমলে স্টক বেশি হবে না, দাম বাড়লে স্টক কম হবে না। স্টক আর দাম আলাদা দুইটা অক্ষ। একই প্রোডাক্ট, একই স্টক, শুধু বিক্রয়মূল্য আলাদা।

ভ্যারিয়েন্টের ক্ষেত্রে সাবধানতা দরকার। ধরুন প্রোডাক্টের তিনটা সাইজ, দাম আলাদা। যদি একটাই fixed campaign_price দিই, ছোট সাইজে লাভ থাকলেও বড় সাইজে লস হতে পারে। তাই আমার সুপারিশ — variant থাকলে fixed price নয়, শতাংশ ছাড়। যেমন ২৫ পার্সেন্ট অফ। তখন প্রতিটা variant-এর নিজের কার্যকর দামের উপর ২৫ পার্সেন্ট কমবে। অ্যাডমিন প্যানেলে প্রতিটা variant-এর আগের দাম, নতুন দাম আর লাভ দেখানো উচিত, সেভ করার আগেই। আর যদি variant না থাকে, তখন fixed campaign_price সবচেয়ে সরল আর পরিষ্কার।

কুপনের প্রশ্নটা আলাদা। ক্যাম্পেইনের দাম তো নিজেই একটা ডিসকাউন্ট। তার উপর আবার ১০ পার্সেন্ট কুপন বসলে লাভ শেষ হয়ে যেতে পারে। তাই campaigns.allow_coupon ডিফল্টে বন্ধ রাখব। বন্ধ থাকলে ক্যাম্পেইনের লাইনগুলো কুপনের হিসাব থেকে বাদ যাবে, অন্য লাইনে কুপন চলবে। যদি ব্যবসায়িক সিদ্ধান্ত হয় কুপন চলবে, তখন কুপন হিসাব হবে ক্যাম্পেইনের দামের উপর, প্রোডাক্টের পুরনো দামের উপর নয়। আমাদের কুপন ইঞ্জিন এখন কার্টের price-ই ব্যবহার করে, তাই ক্যাম্পেইনের দাম কার্টে থাকলে কুপন স্বাভাবিকভাবেই ওই দামের উপর হিসাব হবে। শুধু allow_coupon সুইচটা দেখতে হবে।

মেয়াদ আর নিরাপত্তা। ল্যান্ডিং পেজে ফর্ম লুকিয়ে দিলেই হবে না। কেউ পুরনো পেজ খুলে রাখতে পারে, ক্যাম্পেইন শেষ হওয়ার পরে সাবমিট করতে পারে। তাই `landingOrder`-এ প্রতিবার সার্ভারে তারিখ আর স্ট্যাটাস চেক করতে হবে। মেয়াদ শেষ হলে স্পষ্ট বার্তা — এই অফার শেষ। দাম কখনো রিকোয়েস্ট থেকে নেব না; শুধু campaign_id, product_id, quantity, variant — এই চারটা ইনপুট। দাম সার্ভারেই হিসাব হবে। আরেকটা ঝুঁকি — প্রোডাক্টের দাম পরে কমে গেলে ক্যাম্পেইনের দাম আর ডিসকাউন্ট নাও থাকতে পারে। তখন campaign_price যদি regular price-এর চেয়ে বেশি বা সমান হয়, ক্যাম্পেইনটা অটো-পজ বা সতর্কবার্তা দেবে; গ্রাহককে বেশি দাম চার্জ করবে না।

একটা উদাহরণে পুরো হিসাব দেখি। প্রোডাক্টের সাধারণ দাম ১২০০ টাকা, ক্রয়মূল্য ৮০০ টাকা, স্টক ২০। ক্যাম্পেইনের দাম ৮৯৯ টাকা, campaign_price_enabled চালু, allow_coupon বন্ধ। প্রোডাক্ট ডিটেইলস পেজে দেখাবে ১২০০ টাকা — অপরিবর্তিত। ল্যান্ডিং পেজে দেখাবে ৮৯৯ টাকা, সাথে কাটা ১২০০ টাকা, সেভ ৩০১ টাকা। কার্টে ঢুকবে ৮৯৯ টাকা, options-এ campaign_id সাত, regular_price ১২০০, purchase_price ৮০০। শিপিং ৮০ টাকা, কুপন নেই। orders.amount হবে ৯৭৯ টাকা। order_details-এ sale_price ৮৯৯, regular_price ১২০০, purchase_price ৮০০, campaign_id সাত। স্টক ২০ থেকে ১৯। অর্ডারের পরেও প্রোডাক্ট পেজে দাম ১২০০-ই থাকবে। এই লাইনে লাভ ৯৯ টাকা, ক্যাম্পেইনের ছাড় ৩০১ টাকা। যদি কুপন চালু থাকত এবং ১০ পার্সেন্ট হতো, তাহলে কুপন হতো ৮৯৯-এর ১০ পার্সেন্ট, মানে ৮৯ দশমিক ৯০ টাকা — ১২০০-এর ১০ পার্সেন্ট নয়। এটাই ডাবল ডিসকাউন্টের ভুল এড়ানোর নিয়ম।

এখন অ্যাডমিনের অভিজ্ঞতা। আমাদের লক্ষ্য ১০০ পার্সেন্ট ইউজার ফ্রেন্ডলি, কিন্তু অতি সাধারণও নয়। ক্যাম্পেইন ফর্মে প্রোডাক্ট সিলেক্ট করার সময়ই দেখাবে প্রোডাক্টের দাম, স্টক, variant আছে কি না। তারপর প্রাইসিং প্যানেল — আগের দাম পড়ে থাকবে, অফার প্রাইস লিখবে, সাথে সাথে ছাড়ের পরিমাণ আর শতাংশ দেখাবে। ক্রয়মূল্যের নিচে গেলে লাল সতর্কবার্তা — এই দামে প্রতি ইউনিটে এত টাকা লস। variant থাকলে শুধু শতাংশের ঘর, সাথে প্রতিটা variant-এর প্রিভিউ। কুপনের সুইচ। টেমপ্লেটের কল বাটন, ভিডিও, কাউন্টডাউন — এসবও অন/অফ সুইচ, যাতে অপ্রয়োজনীয় ফিল্ড ভিউতে না যায়। সেভ করার আগে প্রিভিউতে ক্যাম্পেইনের দাম আর কাটা দাম দেখাবে। ভুল হলে বাংলায় স্পষ্ট মেসেজ — অফার প্রাইস শূন্যের বেশি হতে হবে, প্রোডাক্টের দামের চেয়ে কম হতে হবে, variant প্রোডাক্টে শতাংশ ব্যবহার করুন।

তাহলে ল্যান্ডিং পেজের ভ্যালুটা কী রইল? ভ্যালুটা দামের স্থায়িত্বে নয়, সময়সীমা আর উপস্থাপনায়। প্রোডাক্ট পেজ হলো সারা বছরের ক্যাটালগ — সেখানে দাম স্থির, তথ্য পূর্ণ। ল্যান্ডিং পেজ হলো একটা সিজনের দোকান — নির্দিষ্ট সময়ের অফার, নির্দিষ্ট গল্প, নির্দিষ্ট টেমপ্লেট, আর্জেন্সি, আর অ্যাট্রিবিউশন। একই প্রোডাক্ট, কিন্তু গ্রাহক যেন মনে করে এই মুহূর্তে এই অফারটা তার জন্য। ক্যাম্পেইন শেষ হলে ল্যান্ডিং পেজের অফার শেষ; প্রোডাক্ট পেজ আবার তার স্বাভাবিক ভূমিকায়। এটাই ল্যান্ডিং পেজের ব্যবসায়িক মূল্য — প্রোডাক্ট ডুপ্লিকেট না করেই সিজনাল বিক্রি, আর একই ইনভেন্টরি, একই অর্ডার, একই কুরিয়ার।

শেষে পরবর্তী ধাপ। প্রথমে মাইগ্রেশন — campaigns.product_id, campaign_price, campaign_price_enabled, campaign_discount_percent, allow_coupon; আর order_details.campaign_id, regular_price। তারপর CampaignPricing সার্ভিস আর তার টেস্ট। তারপর landingOrder-এ campaign_id, সার্ভার-সাইড দাম, কার্ট ম্যাচিং, variant discount_price ফিক্স। তারপর order_save-এ snapshot। তারপর টেমপ্লেটে দাম আর সুইচ। তারপর অ্যাডমিন প্যানেল। প্রতিটা ধাপে চেক — আসল প্রোডাক্ট, আসল অর্ডার, প্রোডাক্ট পেজের দাম অপরিবর্তিত, অর্ডারের দাম ক্যাম্পেইনের দাম, স্টক এক কম, order_details-এ campaign_id আর regular_price। যতক্ষণ এই পুরো পথ আসল ডাটায় না চলে, ততক্ষণ আমি বলব না কাজ শেষ। ধন্যবাদ, ভাইয়া।
""".strip()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--voice", default=DEFAULT_VOICE)
    parser.add_argument("--rate", default="-5%")
    parser.add_argument("--text-file", type=Path)
    args = parser.parse_args()

    text = args.text_file.read_text(encoding="utf-8").strip() if args.text_file else SCRIPT
    if len(text) < 500:
        print("Script is too short to produce a useful pricing audio.", file=sys.stderr)
        return 2

    chunks = synthesize(text, args.voice, args.rate, args.out)
    seconds = audio_seconds(args.out)
    if seconds is None:
        print(f"Generated {args.out}, but ffprobe could not read its duration.", file=sys.stderr)
        return 1

    print(f"OUT={args.out}")
    print(f"CHARS={len(text)}")
    print(f"CHUNKS={chunks}")
    print(f"SECONDS={seconds:.2f}")
    print(f"BYTES={args.out.stat().st_size}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
